// E-Mail-Kampagnen-Payload validieren
const body = items[0].json.body || items[0].json;

// Pflichtfelder prüfen
if (!body.content) {
  return [{ json: { __error: true, message: 'content ist ein Pflichtfeld' } }];
}
if (!body.recipients && !body.recipientList && !body.segment) {
  return [{ json: { __error: true, message: 'recipients, recipientList oder segment ist erforderlich' } }];
}

// Empfänger-Liste normalisieren
let recipients = [];
if (Array.isArray(body.recipients)) {
  recipients = body.recipients;
} else if (typeof body.recipients === 'string') {
  recipients = body.recipients.split(',').map(e => e.trim()).filter(Boolean);
} else if (body.recipientList) {
  recipients = Array.isArray(body.recipientList) ? body.recipientList : [body.recipientList];
}

// E-Mail-Inhalt aus AI-generierten Content parsen
// Format: "BETREFF: ...

INHALT: ..."
let subject = body.subject || 'Neuigkeiten von uns';
let htmlContent = body.content || '';
let textContent = body.content || '';

// Einfaches Markdown → HTML (Grundversion)
htmlContent = htmlContent
  .replace(/^# (.+)$/gm,   '<h1>$1</h1>')
  .replace(/^## (.+)$/gm,  '<h2>$1</h2>')
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g,   '<em>$1</em>')
  .replace(/\n/g, '<br>');

// HTML-Template
const htmlEmail = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; color: #333; }
    h1, h2, h3 { color: #1a1a1a; }
    .footer { margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; font-size: 12px; color: #999; }
  </style>
</head>
<body>
${htmlContent}
<div class="footer">
  <p>Sie erhalten diese E-Mail, weil Sie sich für unseren Newsletter angemeldet haben.<br>
  <a href="{{unsubscribeUrl}}">Abmelden</a></p>
</div>
</body>
</html>`;

return [{
  json: {
    subject,
    htmlEmail,
    textContent,
    recipients,
    fromName:   body.fromName  || $env.EMAIL_FROM_NAME  || 'AI Orchestra',
    fromEmail:  body.fromEmail || $env.EMAIL_FROM_ADDR  || 'noreply@example.com',
    threadId:   body.threadId  || '',
    clientId:   body.clientId  || 'default',
    totalCount: recipients.length
  }
}];

// Empfänger-Liste in Batches aufteilen (50 pro Batch, Anti-Spam)
const item = items[0].json;
const BATCH_SIZE = 50;
const batches = [];
for (let i = 0; i < item.recipients.length; i += BATCH_SIZE) {
  batches.push(item.recipients.slice(i, i + BATCH_SIZE));
}

return batches.map((batch, idx) => ({
  json: {
    ...item,
    batchRecipients: batch,
    batchIndex:      idx + 1,
    totalBatches:    batches.length
  }
}));

// Kurze Pause zwischen Batches um Spam-Filter zu vermeiden
await new Promise(resolve => setTimeout(resolve, 2000));
return items;

// Kampagnen-Ergebnis zusammenfassen
const allItems = items;
const success = allItems.filter(i => !i.json.__error).length;
const failed  = allItems.filter(i => i.json.__error).length;

return [{
  json: {
    success:     true,
    sent:        success,
    failed:      failed,
    totalBatches: $('In Batches aufteilen (50/Batch)').all().length,
    subject:     $('Kampagne vorbereiten').item.json.subject,
    threadId:    $('Kampagne vorbereiten').item.json.threadId,
    timestamp:   new Date().toISOString()
  }
}];
